def bst_floor(root, key):
    candidate = None
    current = root
    while current is not None:
        if current["key"] == key:
            return current["key"]
        if current["key"] > key:
            current = current["left"]
        else:
            candidate = current["key"]
            current = current["right"]
    return candidate

