def bst_find_report(root, key):
    visited = []
    current = root
    while current is not None:
        visited.append(current["key"])
        if key == current["key"]:
            return {"found": True, "visited": visited}
        if key < current["key"]:
            current = current["left"]
        else:
            current = current["right"]
    return {"found": False, "visited": visited}

